--

CREATE FUNCTION public.fn_descuento_cliente(p_tipo public.tipo_cliente) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    CASE p_tipo
        WHEN 'socio' THEN
            RETURN 10.00;
        WHEN 'distribuidor' THEN
            RETURN 20.00;
        WHEN 'exportador' THEN
            RETURN 30.00;
        ELSE
            RETURN 0.00;
    END CASE;
END;
$$;


