--
-- Name: fn_stock_sala(integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_stock_sala(p_id_sala integer, p_cod_vino integer) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
    SELECT COALESCE(
        (SELECT cantidad 
         FROM stock_sala 
         WHERE id_sala = p_id_sala AND cod_vino = p_cod_vino), 
        0
    );
$$;


