--
-- Name: fn_total_comprobante(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_total_comprobante(p_nro_comprobante integer) RETURNS TABLE(subtotal numeric, descuento numeric, total numeric)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_pct_descuento NUMERIC(5,2);
    v_subtotal      NUMERIC(14,2);
    v_descuento     NUMERIC(14,2);
    v_total         NUMERIC(14,2);
BEGIN
    -- Obtener el porcentaje de descuento asignado al cliente del comprobante
    SELECT c.descuento INTO v_pct_descuento
    FROM comprobante comp
    JOIN cliente c ON c.id_cliente = comp.id_cliente
    WHERE comp.nro = p_nro_comprobante;

    IF NOT FOUND THEN
        v_pct_descuento := 0;
    END IF;

    -- Calcular la suma de subtotales brutos de los renglones
    SELECT COALESCE(SUM(rc.cantidad * rc.precio_unitario), 0)
    INTO v_subtotal
    FROM renglon_comprobante rc
    WHERE rc.nro = p_nro_comprobante;

    -- Calcular el monto de descuento y el neto final
    v_descuento := ROUND(v_subtotal * (v_pct_descuento / 100.0), 2);
    v_total     := v_subtotal - v_descuento;

    RETURN QUERY SELECT v_subtotal, v_descuento, v_total;
END;
$$;


ALTER FUNCTION public.fn_total_comprobante(p_nro_comprobante integer) OWNER TO postgres;

--
-- Name: fn_trg_actualizar_stock_y_totales(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fn_trg_actualizar_stock_y_totales() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_id_sala    INTEGER;
    v_subtotal   NUMERIC(14,2);
    v_descuento  NUMERIC(14,2);
    v_total      NUMERIC(14,2);
BEGIN
    SELECT id_sala INTO v_id_sala FROM comprobante WHERE nro = NEW.nro;

    UPDATE stock_sala
    SET cantidad = cantidad - NEW.cantidad
    WHERE id_sala = v_id_sala AND cod_vino = NEW.cod_vino;

    SELECT subtotal, descuento, total
    INTO v_subtotal, v_descuento, v_total
    FROM fn_total_comprobante(NEW.nro);

    UPDATE comprobante
    SET subtotal  = v_subtotal,
        descuento = v_descuento,
        total     = v_total
    WHERE nro = NEW.nro;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.fn_trg_actualizar_stock_y_totales() OWNER TO postgres;

