CREATE FUNCTION public.fn_trg_auditoria_precio() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF OLD.precio IS DISTINCT FROM NEW.precio THEN
        VALUES (OLD.cod_vino, OLD.precio, NEW.precio, now(), current_user);
    END IF;
    RETURN NEW;
END;
$$;


