CREATE TABLE public.permiso_exportacion (
    id_permiso integer NOT NULL,
    codigo character varying(30) NOT NULL,
    id_cliente integer NOT NULL,
    fecha_emision date NOT NULL,
    fecha_vencimiento date NOT NULL,
    CONSTRAINT ck_permiso_fechas CHECK ((fecha_vencimiento > fecha_emision))
);


ALTER TABLE public.permiso_exportacion OWNER TO postgres;

--
-- Name: permiso_exportacion_id_permiso_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.permiso_exportacion ALTER COLUMN id_permiso ADD GENERATED ALWAYS AS IDENTITY (
    SEQUENCE NAME public.permiso_exportacion_id_permiso_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: renglon_comprobante; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.renglon_comprobante (
    nro integer NOT NULL,
    cod_vino integer NOT NULL,
    cantidad integer NOT NULL,
    precio_unitario numeric(10,2) NOT NULL,
    descuento_pct numeric(5,2) NOT NULL,
    subtotal numeric(14,2) NOT NULL,
    CONSTRAINT ck_renglon_cant CHECK ((cantidad > 0)),
    CONSTRAINT ck_renglon_descuento CHECK (((descuento_pct >= (0)::numeric) AND (descuento_pct <= (100)::numeric))),
    CONSTRAINT ck_renglon_precio CHECK ((precio_unitario > (0)::numeric)),
    CONSTRAINT ck_renglon_subtotal CHECK ((subtotal >= (0)::numeric))
);


ALTER TABLE public.renglon_comprobante OWNER TO postgres;

