    anada smallint NOT NULL,
    volumen_ml integer NOT NULL,
    graduacion numeric(4,2) NOT NULL,
    precio numeric(10,2) NOT NULL,
    cuit_bodega public.cuit_dom NOT NULL,
    CONSTRAINT ck_vino_anada CHECK (((anada >= 1900) AND (anada <= 2100))),
    CONSTRAINT ck_vino_graduacion CHECK (((graduacion >= (5)::numeric) AND (graduacion <= (20)::numeric))),
    CONSTRAINT ck_vino_precio CHECK ((precio > (0)::numeric)),
    CONSTRAINT ck_vino_volumen CHECK ((volumen_ml > 0))
);


ALTER TABLE public.vino OWNER TO postgres;

