--
-- Name: vw_documentos_pendientes; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_documentos_pendientes AS
 SELECT 'Ingreso'::text AS tipo_documento,
    i.cod_ingreso AS nro_documento,
    i.fecha,
    i.estado,
    (CURRENT_DATE - i.fecha) AS dias_antiguedad,
    b.razon_social AS entidad_asociada
   FROM (public.ingreso i
     JOIN public.bodega b ON (((i.cuit_bodega)::bpchar = (b.cuit)::bpchar)))
  WHERE (i.estado <> 'procesado'::public.estado_documento)
UNION ALL
 SELECT 'Transferencia'::text AS tipo_documento,
    t.nro_solicitud AS nro_documento,
    t.fecha_confeccion AS fecha,
    t.estado,
    (CURRENT_DATE - t.fecha_confeccion) AS dias_antiguedad,
    ('Sala '::text || (s.numero)::text) AS entidad_asociada
   FROM (public.transferencia t
     JOIN public.sala_venta s ON ((t.id_sala = s.id_sala)))
  WHERE (t.estado <> 'procesado'::public.estado_documento);


ALTER VIEW public.vw_documentos_pendientes OWNER TO postgres;

--
-- Name: vw_stock_total_vino; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_stock_total_vino AS
 SELECT v.cod_vino,
    v.nombre AS vino,
    v.tipo AS tipo_vino,
    v.anada,
    v.precio,
    COALESCE(sd.cantidad, 0) AS stock_deposito_central,
    COALESCE(sum(ss.cantidad), (0)::bigint) AS stock_total_salas,
    (COALESCE(sd.cantidad, 0) + COALESCE(sum(ss.cantidad), (0)::bigint)) AS stock_total_sistema
   FROM ((public.vino v
     LEFT JOIN public.stock_deposito sd ON ((v.cod_vino = sd.cod_vino)))
     LEFT JOIN public.stock_sala ss ON ((v.cod_vino = ss.cod_vino)))
  GROUP BY v.cod_vino, v.nombre, v.tipo, v.anada, v.precio, sd.cantidad;


ALTER VIEW public.vw_stock_total_vino OWNER TO postgres;

--
-- Name: vw_ventas_mensuales_sala; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.vw_ventas_mensuales_sala AS
 SELECT s.id_sala,
    ('Sala '::text || (s.numero)::text) AS sala_venta,
    (EXTRACT(year FROM c.fecha))::integer AS anio,
    (EXTRACT(month FROM c.fecha))::integer AS mes,
    count(c.nro) AS cantidad_comprobantes,
    sum(c.subtotal) AS subtotal_acumulado,
    sum(c.descuento) AS descuento_acumulado,
    sum(c.total) AS total_facturado
   FROM (public.sala_venta s
     JOIN public.comprobante c ON ((s.id_sala = c.id_sala)))
  GROUP BY s.id_sala, s.numero, (EXTRACT(year FROM c.fecha)), (EXTRACT(month FROM c.fecha));


ALTER VIEW public.vw_ventas_mensuales_sala OWNER TO postgres;

